def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, 45.0)
        return min(budget, 18.0)

    opp_bids = []
    eric_bid = None
    active_threats = 0
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            opp_bids.append(float(bid))
            if bid > 0:
                active_threats += 1
        if agent_id == 'Eric' and bid is not None:
            eric_bid = float(bid)

    if eric_bid is None:
        eric_bid = 94.0

    if supply >= 24:
        scarcity = 'low'
    elif supply >= 20:
        scarcity = 'medium'
    else:
        scarcity = 'high'

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if urgent:
        target = max(62.0, min(eric_bid + 2.0, 110.0))
    elif scarcity == 'high':
        target = max(58.0, min(eric_bid - 4.0, 92.0))
    elif scarcity == 'medium':
        if pressured:
            target = max(46.0, min(eric_bid - 12.0, 78.0))
        else:
            target = 28.0 if active_threats <= 1 else 36.0
    else:
        if pressured:
            target = 34.0
        else:
            target = 14.0

    if day >= 8:
        if urgent:
            target += 8.0
        elif hp >= 6 and budget < 120:
            target -= 6.0

    if budget <= 0:
        return 0.0

    if budget < target:
        if urgent:
            return float(budget)
        return min(float(budget), 20.0)

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no one alive, bid conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many water units might be needed from supply
    # (Used only to calibrate aggression.)
    # With supply 15-25 and WATER_REQ=9, typically 1 unit is enough; sometimes 2.
    expected_units = int(supply / float(WATER_REQ))  # safe integer
    if expected_units < 1:
        expected_units = 1

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Pressure detection: if someone already spent near salary yesterday, we counter.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid depends on supply pressure and our HP.
    # If supply is low, winning costs more relative to survival; bid slightly higher to avoid losing.
    supply_low = supply <= (MIN_SUPPLY + 0.5)

    # Aggression tiers
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # They were willing to burn money; we should match enough to secure water.
        if my_hp > 3:
            bid = DAILY_SALARY * 0.35
        else:
            bid = DAILY_SALARY * 0.95
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        bid = DAILY_SALARY * 0.55
        if supply_low:
            bid *= 1.15
    else:
        bid = DAILY_SALARY * 0.48
        if supply_low:
            bid *= 1.08

    # Small bump to beat likely midrange bids when supply allows only limited allocations.
    # Use expected_units: when supply is closer to 15, allocations are tighter.
    if expected_units == 1:
        bid += 2.5
    else:
        bid += 1.0

    # Never exceed our budget; also avoid bidding too low.
    min_reasonable = 5.0
    bid = float(min(my_budget, max(bid, min_reasonable)))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        if my_status['hp'] < 4:
            return min(my_status['budget'], max_prev + 5.0)
        return min(my_status['budget'], max(avg_prev * 0.9, 45.0))
    return min(my_status['budget'], 50.0)
